package com.greenocean.backend;
import com.greenocean.backend.auth.service.*;import com.greenocean.backend.auth.entity.*;import com.greenocean.backend.auth.config.*;
import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseEFSecurityUnitTest {
 SessionPolicy policy(){return new SessionPolicy(Duration.ofHours(24),Duration.ofMinutes(30),Duration.ofDays(30),Duration.ofHours(24),Duration.ofHours(12),Duration.ofMinutes(30),Duration.ofMinutes(10));}
 @Test @Tag("happy") void approvedPlatformAndScopeBoundsAreDistinct(){var p=policy();assertThat(p.overall("WEB","MEMBER")).isEqualTo(Duration.ofDays(1));assertThat(p.overall("MOBILE","MEMBER")).isEqualTo(Duration.ofDays(30));assertThat(p.idle("MOBILE","MEMBER")).isEqualTo(Duration.ofDays(1));assertThat(p.overall("MOBILE","PRIVILEGED")).isEqualTo(Duration.ofHours(12));assertThat(p.overall("WEB","PENDING")).isEqualTo(Duration.ofHours(1));assertThat(p.idle("MOBILE","PENDING")).isEqualTo(Duration.ofMinutes(15));}
 @Test @Tag("creative") void refreshDoesNotMoveOverallOrMeaningfulActivity(){Instant now=Instant.parse("2026-10-26T00:00:00Z");var s=new UserSession(UUID.randomUUID(),null,"synthetic",null,now.plus(Duration.ofDays(30)));s.initialize("WEB","MEMBER",now,policy());Instant overall=s.getOverallExpiresAt(),idle=s.getIdleExpiresAt(),activity=s.getLastActivityAt();s.rotate("rotated",now.plus(Duration.ofDays(60)));assertThat(s.getExpiresAt()).isEqualTo(overall);assertThat(s.getOverallExpiresAt()).isEqualTo(overall);assertThat(s.getIdleExpiresAt()).isEqualTo(idle);assertThat(s.getLastActivityAt()).isEqualTo(activity);}
 @Test @Tag("confused") void exactIdleAndOverallBoundariesFailClosed(){Instant now=Instant.parse("2026-10-26T00:00:00Z");var s=new UserSession(UUID.randomUUID(),null,"synthetic",null,now.plus(Duration.ofDays(30)));s.initialize("WEB","MEMBER",now,policy());assertThat(s.isUsableAt(now.plusSeconds(1799))).isTrue();assertThat(s.isUsableAt(now.plusSeconds(1800))).isFalse();assertThat(s.isUsableAt(now.plusSeconds(86400))).isFalse();s.revoke();assertThat(s.isUsableAt(now)).isFalse();}
 @Test @Tag("malicious") void invalidPolicyCannotStart(){assertThatThrownBy(()->new SessionPolicy(Duration.ZERO,Duration.ofMinutes(30),Duration.ofDays(30),Duration.ofDays(1),Duration.ofHours(12),Duration.ofMinutes(30),Duration.ofMinutes(10))).isInstanceOf(IllegalArgumentException.class);}
 @Test @Tag("confused") void malformedModernAndLegacyHashesAreGenericFailures(){var encoder=new CompatiblePasswordEncoder();for(String stored:List.of("{pbkdf2}not-hex","$2b$invalid","DELETED","{unknown}secret",""))assertThat(encoder.matches("a synthetic passphrase",stored)).isFalse();}
 @Test @Tag("creative") void unicodePasswordBoundsAndNoArbitraryCompositionRule(){assertThatCode(()->PasswordPolicy.validate("🌊ایمن ".repeat(8))).doesNotThrowAnyException();assertThatCode(()->PasswordPolicy.validate("اب".repeat(10))).doesNotThrowAnyException();assertThatThrownBy(()->PasswordPolicy.validate("🌊".repeat(129))).isInstanceOf(IllegalArgumentException.class);}
}
